(function(){'use strict';
const KEY='nawaf-hq-v5';
const $=s=>document.querySelector(s);
function read(){try{return JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch{return {}}}
function write(s,reason='finance'){localStorage.setItem(KEY,JSON.stringify(s));window.dispatchEvent(new CustomEvent('nawaf:state-updated',{detail:{reason}}));window.dispatchEvent(new CustomEvent('nawaf:activity-updated'))}
function uid(p){return p+Date.now().toString(36)+Math.random().toString(36).slice(2,6)}
function analyst(){const s=read();s.employees=Array.isArray(s.employees)?s.employees:[];let e=s.employees.find(x=>x.id==='finance');if(!e){e={id:'finance',name:'راكان',role:'المحلل المالي والاستثماري',department:'الاستثمار والتحليل المالي',status:'READY',task:'',productivity:100,mission:'تحليل الأسهم والشركات والقوائم المالية والتقييمات والمخاطر والفرص. لا ينفذ شراء أو بيع دون موافقة نواف.',permissions:{tasks:true,projects:false,review:true,code:false,deploy:false,external:true}};s.employees.push(e);write(s,'finance-analyst-created')}return e}
function ensureModal(){let m=$('#finance-modal');if(m)return m;m=document.createElement('div');m.id='finance-modal';m.className='v9-modal';m.innerHTML='<div class="v9-dialog"><div id="finance-body"></div></div>';document.body.appendChild(m);m.addEventListener('click',e=>{if(e.target===m||e.target.closest('[data-fin-close]'))m.classList.remove('show')});return m}
function open(){const e=analyst(),m=ensureModal();m.querySelector('#finance-body').innerHTML=`<div class="v9-dialog-head"><div><span>FINANCIAL ANALYST</span><h2>${e.name} — المحلل المالي</h2><p>تحليل استثماري منظم مع فصل الحقائق عن الرأي. لا شراء أو بيع تلقائي.</p></div><button data-fin-close>×</button></div><form id="finance-form" class="v9-form"><label>نوع التحليل<select name="workflow"><option value="stock">تحليل سهم</option><option value="compare">مقارنة شركات</option><option value="valuation">تقييم وقيمة عادلة</option><option value="earnings">تحليل نتائج وأرباح</option><option value="portfolio">مراجعة محفظة</option><option value="market">ملخص سوق وفرص ومخاطر</option></select></label><label>السهم / الشركة<input name="symbol" placeholder="مثال: 2222 أو AAPL"></label><label>الأفق<select name="horizon"><option value="long">طويل</option><option value="medium">متوسط</option><option value="short">قصير</option></select></label><label>المخاطر<select name="risk"><option value="balanced">متوازن</option><option value="conservative">محافظ</option><option value="aggressive">مرتفع</option></select></label><label class="v9-full">وش تبي تعرف؟<textarea name="question" rows="5" required placeholder="حلل الشركة ماليًا، اذكر المحفزات والمخاطر، وهل التقييم الحالي منطقي؟"></textarea></label><div class="v9-full" style="padding:10px 12px;border:1px solid #ffffff14;border-radius:12px;color:#aeb8c8;font-size:12px;line-height:1.7">عند طلب سعر حالي أو خبر جديد أو نتائج حديثة: لازم يعتمد على مصدر حديث. إذا البيانات غير متاحة، يصرّح بذلك بدل التخمين.</div><div class="v9-full v9-actions"><button type="button" data-fin-close>إلغاء</button><button class="primary" type="submit">ابدأ التحليل</button></div></form>`;m.classList.add('show');$('#finance-form').onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.currentTarget),q=read(),emp=(q.employees||[]).find(x=>x.id==='finance')||analyst();const wf=String(f.get('workflow')||'stock'),symbol=String(f.get('symbol')||'').trim(),question=String(f.get('question')||'').trim(),horizon=String(f.get('horizon')||'long'),risk=String(f.get('risk')||'balanced');if(!question)return;const labels={stock:'تحليل سهم',compare:'مقارنة استثمارية',valuation:'تقييم مالي',earnings:'تحليل أرباح',portfolio:'مراجعة محفظة',market:'ملخص سوق'};const details=`${labels[wf]||'تحليل مالي'}\nالأصل/الشركة: ${symbol||'غير محدد'}\nالأفق: ${horizon}\nتحمل المخاطر: ${risk}\nالسؤال: ${question}\n\nقواعد إلزامية: افصل الحقائق عن الرأي، اذكر الافتراضات والمخاطر، لا تختلق سعراً أو رقماً حالياً، ولا تنفذ أي شراء أو بيع أو تحويل أموال. إذا المهمة تحتاج بيانات سوق حالية وغير متوفرة فأرجع NEEDS_TOOL بوضوح.`;const task={id:uid('t'),title:`${labels[wf]||'تحليل مالي'}: ${(symbol||question).slice(0,70)}`,details,employeeId:emp.id,projectId:'',status:'READY',progress:0,kind:'RESEARCH',priority:'HIGH',createdAt:new Date().toISOString(),createdBy:'NAWAF',domain:'FINANCE'};q.tasks=Array.isArray(q.tasks)?q.tasks:[];q.tasks.unshift(task);emp.status='READY';emp.task=task.title;q.activity=Array.isArray(q.activity)?q.activity:[];q.activity.unshift({id:uid('a'),text:`تم تكليف ${emp.name}: ${task.title}`,type:'REAL',at:new Date().toISOString()});write(q,'finance-analysis-requested');m.classList.remove('show');setTimeout(()=>window.NawafAgents?.runTask?.(task.id).catch(()=>{}),160)}}
function inject(){analyst();if(document.querySelector('[data-finance-open]'))return;const strip=document.querySelector('.v9-control-strip');if(!strip)return;const b=document.createElement('button');b.type='button';b.setAttribute('data-finance-open','1');b.textContent='محلل مالي';b.addEventListener('click',open);strip.appendChild(b)}
let t;const obs=new MutationObserver(()=>{clearTimeout(t);t=setTimeout(inject,100)});function boot(){obs.observe(document.body,{childList:true,subtree:true});inject()}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
window.NawafFinance={open,analyst};
})();